<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {availableProtocols} from './planProtocols';
type Row=Record<string,any>;const props=defineProps<{model:Row,groups:Row[],ready:boolean}>();const removed=ref<string[]>([]);
const choices=computed(()=>availableProtocols(props.groups,props.model.group_ids));
watch(()=>[props.model.group_ids,props.groups,props.ready],()=>{if(!props.ready)return;const keep=(props.model.protocols||[]).filter((p:string)=>choices.value.includes(p));removed.value=(props.model.protocols||[]).filter((p:string)=>!keep.includes(p));props.model.protocols=keep},{deep:true,immediate:true});
</script>
<template><section class="selection-panel"><h3>授权星枢用户组</h3><p class="muted">选择用户组后，再勾选该组实际提供的独立计费协议；不会自动勾选协议。共享密钥节点不可用于售卖。</p><label v-for="g in groups" :key="g.id" class="multi"><input type="checkbox" :value="g.id" v-model="model.group_ids">{{g.name}}<small>{{(g.services||[]).map((s:Row)=>s.name+(s.managed_users?'':'（共享，不可售）')).join('、')}}</small></label><p v-if="!ready" class="alert error">暂未读取到用户组，请检查星枢连接后再保存协议配置。</p><p v-else-if="!groups.length" class="muted">尚无可选用户组。</p><h3>允许的协议</h3><div class="protocol-options"><label v-for="p in choices" :key="p" class="multi"><input type="checkbox" v-model="model.protocols" :value="p">{{p.toUpperCase()}}</label></div><p v-if="ready&&!choices.length" class="muted">所选用户组没有可计费协议。</p><p class="selected-protocols">当前已选：<strong>{{model.protocols?.length?model.protocols.map((p:string)=>p.toUpperCase()).join(' / '):'无'}}</strong></p><p v-if="removed.length" class="alert">原选择 {{removed.join(' / ').toUpperCase()}} 不属于当前用户组，已从本次编辑中移除。</p></section></template>
<style scoped>.selection-panel{border:1px solid #e2e8ef;background:#fafcfd;border-radius:12px;padding:20px;margin:20px 0}.protocol-options{display:flex;flex-wrap:wrap;gap:10px}.protocol-options .multi{padding:8px 12px;border:1px solid #dae2ec;border-radius:8px;background:white}.selected-protocols{font-size:13px;margin:12px 0 0}.selection-panel h3{margin:14px 0}.selection-panel>h3:first-child{margin-top:0}</style>
